<?php require __DIR__.'/bootstrap.php';require_login();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);if($a==='save'){$title=trim((string)($_POST['title']??''));$url=trim((string)($_POST['url']??'#'));$sort=(int)($_POST['sort_order']??0);if($id)$pdo->prepare('UPDATE tips SET title=?,url=?,sort_order=? WHERE id=?')->execute([$title,$url,$sort,$id]);else $pdo->prepare('INSERT INTO tips(title,url,sort_order,active) VALUES(?,?,?,1)')->execute([$title,$url,$sort]);}elseif($a==='delete'&&$id)$pdo->prepare('DELETE FROM tips WHERE id=?')->execute([$id]);flash('success','Tips updated.');header('Location: tips.php');exit;}$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM tips WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query('SELECT * FROM tips ORDER BY sort_order,id')->fetchAll();$pageTitle='Home Tips';$active='tips';require __DIR__.'/_header.php';?><p class="eyebrow">HOME IMPROVEMENT TIPS</p><h1>Educational content</h1><section class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h((string)($edit['id']??''))?>"><label>Title<input name="title" required value="<?=h($edit['title']??'')?>"></label><div class="two-col"><label>URL<input name="url" value="<?=h($edit['url']??'#')?>"></label><label>Order<input type="number" name="sort_order" value="<?=h((string)($edit['sort_order']??0))?>"></label></div><button>Save tip</button></form></section><div class="table-wrap"><table class="admin-table"><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['title'])?></td><td><a class="button secondary" href="?edit=<?=$r['id']?>">Edit</a></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/_footer.php';
